/* ---- unit RES12 ---- */
/* The readied-item bonus accumulator AddReadiedItemBonus fills for RecalcCombatValues: five signed
       bytes (with the flag byte the second var parameter points at). RecalcCombatValues clears all five,
       stores the dexterity adjustment in DexAdjust, and sums all five as Values into ArmourClassValue (+$111);
       only BestValue, PlusSum and BestPlus (minus two) go into RearArmourClassValue (+$112). */
typedef struct TBonus {
  union {
    struct {
      u8 DexAdjust;
      s8 KindBonus;
      s8 PlusSum;
      s8 BestPlus;
      s8 BestValue;
    };
    struct {
      s8 Values[5];
    };
  };
} TBonus;
/* Bits of ItemTable[item kind].Flags (DS:5582; 129 sixteen-byte rows indexed by item kind, POOLVARS):
       which attack bonuses the item kind gets. The readied weapon's item kind picks the row. */
enum { WeaponFlagSlot11Plus = 1 };  /* add the plus of slot item 11 (+$F8) */
enum { WeaponFlagDexToHit = 2 };  /* the attack adds the dexterity roll adjustment */
enum { WeaponFlagStrength = 4 };  /* the attack adds the strength roll and damage adjustments */
enum { WeaponFlagMelee = 0x10 };  /* the kind can strike with the readied weapon itself (2E46, 2E8B) */
enum { WeaponFlagAmmo = 0x8 };  /* the kind fires an ammo item: slot 11 or 12 (ChooseAttackItem) */
enum { WeaponFlagSlot12Plus = 0x80 };  /* add the plus of slot item 12 (+$FC) */
